// aim.cpp
// World-to-screen projection + smoothed crosshair delta inside a 240 px cone.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DSMOKE_TEST /O2 /W4 aim.cpp /link user32.lib
//
// Exported helpers:
//   WorldToScreen()   – project a 3-D world position onto the 2-D screen
//   GetAimDelta()     – return a smoothed (dx, dy) toward the nearest entity
//                       head inside a 240 px screen-space cone, or {0,0}

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cstring>
#include <cfloat>
#include <cstdio>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

struct Matrix4x4 {
    float m[4][4];
};

static inline float Vec3Dot(const Vec3& a, const Vec3& b)
{
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

static inline float Vec2Length(const Vec2& v)
{
    return sqrtf(v.x * v.x + v.y * v.y);
}

// ---------------------------------------------------------------------------
// ViewParams – everything the caller must supply about the camera
// ---------------------------------------------------------------------------

struct ViewParams {
    Matrix4x4 viewProjMatrix; // combined view * projection (row-major)
    float     screenW;        // viewport width  in pixels
    float     screenH;        // viewport height in pixels
};

// ---------------------------------------------------------------------------
// EntityRecord – one entry from the entity list
// ---------------------------------------------------------------------------

struct EntityRecord {
    Vec3  headPosition;   // world-space head bone origin
    bool  alive;          // skip dead/spectator slots
};

// ---------------------------------------------------------------------------
// WorldToScreen
//
// Projects a world-space Vec3 through the supplied view-projection matrix
// into viewport pixel coordinates.  Returns false when the point is behind
// the near plane (w <= 0).
// ---------------------------------------------------------------------------

bool WorldToScreen(const Vec3& world,
                   const ViewParams& vp,
                   Vec2& screenOut)
{
    const Matrix4x4& m = vp.viewProjMatrix;

    // Transform to clip space: clip = M * [world.x, world.y, world.z, 1]
    float clipX = world.x * m.m[0][0] + world.y * m.m[1][0]
                + world.z * m.m[2][0] + m.m[3][0];
    float clipY = world.x * m.m[0][1] + world.y * m.m[1][1]
                + world.z * m.m[2][1] + m.m[3][1];
    float clipW = world.x * m.m[0][3] + world.y * m.m[1][3]
                + world.z * m.m[2][3] + m.m[3][3];

    if (clipW <= 0.0f)
        return false;   // behind near plane

    float invW = 1.0f / clipW;
    float ndcX =  clipX * invW;  // [-1, 1]
    float ndcY =  clipY * invW;  // [-1, 1]

    // Map NDC to pixel coordinates (Y flipped: NDC +1 == top of screen)
    screenOut.x = ( ndcX + 1.0f) * 0.5f * vp.screenW;
    screenOut.y = (-ndcY + 1.0f) * 0.5f * vp.screenH;

    return true;
}

// ---------------------------------------------------------------------------
// GetAimDelta
//
// Iterates `entities[0..count)`, projects each live entity's head, keeps the
// one whose projected screen position is both inside a 240 px radius around
// the screen centre and closest to it, then returns a delta (dx, dy) in
// pixels smoothed by `smoothFactor` (0 < smoothFactor <= 1, where 1 means
// snap, 0.1 means heavy smoothing).
//
// Returns {0, 0} when no eligible target is found.
// ---------------------------------------------------------------------------

Vec2 GetAimDelta(const EntityRecord* entities,
                 int                 count,
                 const ViewParams&   vp,
                 float               smoothFactor)   // 0 < x <= 1
{
    constexpr float kConeRadiusPx = 240.0f;

    // Clamp smoothing factor to a sane range
    if (smoothFactor <= 0.0f) smoothFactor = 0.01f;
    if (smoothFactor >  1.0f) smoothFactor = 1.0f;

    Vec2  crosshair = { vp.screenW * 0.5f, vp.screenH * 0.5f };
    float bestDist  = kConeRadiusPx; // only accept targets strictly inside
    Vec2  bestScreen = { 0.0f, 0.0f };
    bool  found = false;

    for (int i = 0; i < count; ++i) {
        const EntityRecord& e = entities[i];
        if (!e.alive) continue;

        Vec2 s;
        if (!WorldToScreen(e.headPosition, vp, s)) continue;

        Vec2  delta = { s.x - crosshair.x, s.y - crosshair.y };
        float dist  = Vec2Length(delta);

        if (dist < bestDist) {
            bestDist   = dist;
            bestScreen = s;
            found      = true;
        }
    }

    if (!found)
        return { 0.0f, 0.0f };

    // Raw delta from crosshair to best head
    Vec2 raw = { bestScreen.x - crosshair.x,
                 bestScreen.y - crosshair.y };

    // Apply smooth factor: move a fraction of the remaining distance
    return { raw.x * smoothFactor, raw.y * smoothFactor };
}

// ---------------------------------------------------------------------------
// Smoke test
// ---------------------------------------------------------------------------

#ifdef SMOKE_TEST

static void PrintVec2(const char* tag, const Vec2& v)
{
    printf("%s  x=%.3f  y=%.3f\n", tag, v.x, v.y);
}

int main()
{
    // Build a trivial orthographic-style view-proj matrix that maps world XY
    // directly to NDC so we can reason about the numbers by hand.
    //   NDC_x = world_x / (W/2)  =>  NDC_x = 1 when world_x == W/2
    //   NDC_y = world_y / (H/2)  (note: Y not flipped in this test matrix)
    //   W = 1920, H = 1080

    ViewParams vp{};
    vp.screenW = 1920.0f;
    vp.screenH = 1080.0f;
    // Identity-ish matrix scaled so world units == pixels at z == 0
    std::memset(&vp.viewProjMatrix, 0, sizeof(vp.viewProjMatrix));
    vp.viewProjMatrix.m[0][0] = 2.0f / vp.screenW;  // x scale
    vp.viewProjMatrix.m[1][1] = 2.0f / vp.screenH;  // y scale (up == +Y in NDC)
    vp.viewProjMatrix.m[2][2] = 1.0f;
    vp.viewProjMatrix.m[3][3] = 1.0f;

    // --- WorldToScreen test ---
    Vec3 worldPt = { vp.screenW * 0.5f,   // x == screen centre
                     vp.screenH * 0.5f,   // y == screen centre
                     0.0f };
    Vec2 screen;
    bool ok = WorldToScreen(worldPt, vp, screen);
    printf("WorldToScreen (expect ~960, ~270): ok=%d  ", ok);
    PrintVec2("", screen);
    // Note: our test matrix is +Y-up in world but WorldToScreen flips Y,
    // so world_y == H/2 maps to NDC +0.5 → screen_y = (-0.5+1)*0.5*H = 0.25*H

    // --- GetAimDelta test ---
    // Place a target 50 px right and 30 px below the crosshair in screen space.
    // With our matrix: world_x = screen_x (at z==0)
    float cx = vp.screenW * 0.5f;
    float cy = vp.screenH * 0.5f;

    // screen_y = (-ndc_y + 1) * 0.5 * H
    // ndc_y    = world_y * (2/H)
    // => screen_y = (-(world_y*2/H) + 1) * 0.5 * H = H/2 - world_y
    // so: world_y = H/2 - screen_y
    EntityRecord ents[3];
    // Target 0: head at screen (cx+50, cy+30) → world (cx+50, cy-30, 0)
    ents[0].headPosition = { cx + 50.0f, cy - 30.0f, 0.0f };
    ents[0].alive = true;
    // Target 1: outside cone (300 px right)
    ents[1].headPosition = { cx + 300.0f, cy, 0.0f };
    ents[1].alive = true;
    // Target 2: dead
    ents[2].headPosition = { cx + 10.0f, cy, 0.0f };
    ents[2].alive = false;

    float smooth = 0.3f;
    Vec2 delta = GetAimDelta(ents, 3, vp, smooth);
    printf("GetAimDelta (expect ~%.1f, ~%.1f): ", 50.0f * smooth, 30.0f * smooth);
    PrintVec2("", delta);

    // No-target test
    ents[0].alive = false;
    ents[1].alive = false;
    Vec2 noTarget = GetAimDelta(ents, 3, vp, smooth);
    printf("GetAimDelta no targets (expect 0, 0): ");
    PrintVec2("", noTarget);

    return 0;
}

#endif // SMOKE_TEST
